-- Creator marketplace verified reviews, disputes and protected delivery records.
create table public.marketplace_reviews(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.marketplace_listings(id) on delete cascade,order_id uuid not null unique references public.marketplace_orders(id) on delete cascade,buyer_id uuid not null references auth.users(id) on delete cascade,seller_id uuid not null references auth.users(id) on delete cascade,rating integer not null check(rating between 1 and 5),title text,body text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.marketplace_disputes(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.marketplace_orders(id) on delete cascade,opened_by uuid not null references auth.users(id) on delete cascade,reason text not null check(reason in ('not_received','not_as_described','access_issue','license_issue','refund_request','fraud','other')),details text not null,status text not null default 'open' check(status in ('open','seller_response','under_review','resolved_buyer','resolved_seller','closed')),resolution_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.marketplace_deliveries(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.marketplace_orders(id) on delete cascade,seller_id uuid not null references auth.users(id) on delete cascade,buyer_id uuid not null references auth.users(id) on delete cascade,delivery_type text not null,delivery_reference text,license_key_ciphertext text,instructions text,status text not null default 'pending' check(status in ('pending','ready','delivered','revoked')),delivered_at timestamptz,created_at timestamptz not null default now());
alter table public.marketplace_reviews enable row level security;alter table public.marketplace_reviews force row level security;alter table public.marketplace_disputes enable row level security;alter table public.marketplace_disputes force row level security;alter table public.marketplace_deliveries enable row level security;alter table public.marketplace_deliveries force row level security;
revoke all on public.marketplace_reviews,public.marketplace_disputes,public.marketplace_deliveries from anon,authenticated;grant select,insert,update on public.marketplace_reviews to authenticated;grant select,insert,update on public.marketplace_disputes to authenticated;grant select on public.marketplace_deliveries to authenticated;grant all on public.marketplace_reviews,public.marketplace_disputes,public.marketplace_deliveries to service_role;
create policy marketplace_reviews_read on public.marketplace_reviews for select to authenticated using(true);create policy marketplace_reviews_verified_insert on public.marketplace_reviews for insert to authenticated with check(buyer_id=(select auth.uid()) and exists(select 1 from public.marketplace_orders o where o.id=order_id and o.buyer_id=(select auth.uid()) and o.listing_id=listing_id and o.status in ('paid','fulfilled')));create policy marketplace_reviews_owner_update on public.marketplace_reviews for update to authenticated using(buyer_id=(select auth.uid())) with check(buyer_id=(select auth.uid()));
create policy marketplace_disputes_parties_read on public.marketplace_disputes for select to authenticated using(exists(select 1 from public.marketplace_orders o where o.id=order_id and (o.buyer_id=(select auth.uid()) or o.seller_id=(select auth.uid()))));create policy marketplace_disputes_buyer_insert on public.marketplace_disputes for insert to authenticated with check(opened_by=(select auth.uid()) and exists(select 1 from public.marketplace_orders o where o.id=order_id and o.buyer_id=(select auth.uid())));create policy marketplace_disputes_parties_update on public.marketplace_disputes for update to authenticated using(exists(select 1 from public.marketplace_orders o where o.id=order_id and (o.buyer_id=(select auth.uid()) or o.seller_id=(select auth.uid()))));
create policy marketplace_deliveries_parties_read on public.marketplace_deliveries for select to authenticated using(buyer_id=(select auth.uid()) or seller_id=(select auth.uid()));